// OpenCascade HLR + BRep section. Output in drawing coordinates (mm); no mesh visibility approximation.
export function occDraw(oc,shapes,views,{steelCount=shapes.length}={}){
 const sub=(a,b)=>a.map((x,i)=>x-b[i]),dot=(a,b)=>a.reduce((s,x,i)=>s+x*b[i],0),cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
 const out=[];for(const v of views){let owned=[];const own=x=>(owned.push(x),x);try{let x=v.x,y=v.y,z=cross(x,y),origin=v.origin,pt=own(new oc.gp_Pnt(...origin)),normal=own(new oc.gp_Dir(...z)),xd=own(new oc.gp_Dir(...x));
 function edges(shape,world=false){if(!shape||shape.IsNull())return [];let m=own(oc.ReplicadEdgeMeshExtractor.extract(shape,.05,.12)),a=new Float32Array(oc.wasmMemory.buffer,m.getLinesPtr(),m.getLinesSize()),r=[];for(let i=0;i+5<a.length;i+=6){let p=Array.from(a.slice(i,i+3)),q=Array.from(a.slice(i+3,i+6));if(world){p=sub(p,origin);q=sub(q,origin);p=[dot(p,x),dot(p,y)];q=[dot(q,x),dot(q,y)];}else{p=p.slice(0,2);q=q.slice(0,2);}if(Math.hypot(p[0]-q[0],p[1]-q[1])>1e-5)r.push([...p,...q]);}return r;}
 function dedup(a){let m=new Map;for(let p of a){let k=[p.slice(0,2),p.slice(2)].map(q=>q.map(v=>Math.round(v*1000)).join(',')).sort().join('|');if(!m.has(k))m.set(k,p);}return m;}
 if(v.section){let plane=own(new oc.gp_Pln(pt,normal)),visible=[],sectionGroups=[];for(let [shapeIndex,s] of shapes.entries()){let sec=own(new oc.BRepAlgoAPI_Section(s.wrapped,plane,true));if(!sec.IsDone())throw Error('חישוב חתך נכשל');let group=[...dedup(edges(own(sec.Shape()),true)).values()];if(shapeIndex<steelCount)sectionGroups.push(group);visible.push(...group);}out.push({...v,visible:[...dedup(visible).values()],hidden:[],sectionGroups});}
 else {let ax=own(new oc.gp_Ax2(pt,normal,xd)),projector=own(new oc.HLRAlgo_Projector(ax)),algo=own(new oc.HLRBRep_Algo());for(let s of shapes)algo.Add(s.wrapped,0);algo.Projector(projector);algo.Update();algo.Hide();let h=own(new oc.HLRBRep_HLRToShape(algo));let visible=dedup([...edges(own(h.VCompound())),...edges(own(h.OutLineVCompound())),...edges(own(h.Rg1LineVCompound()))]),hidden=dedup([...edges(own(h.HCompound())),...edges(own(h.OutLineHCompound()))]);for(let k of visible.keys())hidden.delete(k);out.push({...v,visible:[...visible.values()],hidden:[...hidden.values()]});}
 }finally{for(let a of owned.reverse())try{a.delete()}catch{}}}return out;
}
